-- +goose StatementEnd
REVOKE ALL ON FUNCTION control_plane.integration_github_legacy_capabilities(text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION control_plane.integration_github_legacy_capabilities(text,text,text,text) TO control_plane_runtime;

-- +goose StatementBegin
DO $admission$
DECLARE
    v_signature regprocedure := 'control_plane.integration_grant_admission(uuid,uuid,uuid,text,text,text,text,text,text,text[])'::regprocedure;
    v_definition text;
    v_before text := E'                ELSE (\n                    SELECT revision.content::jsonb #> ''{spec,capabilities}''';
    v_after text := E'                WHEN connection.definition_key=''github''\n                  AND control_plane.integration_github_legacy_capabilities(\n                    definition.definition_version,definition.digest,connection.definition_version,connection.definition_digest) IS NOT NULL\n                THEN control_plane.integration_github_legacy_capabilities(\n                    definition.definition_version,definition.digest,connection.definition_version,connection.definition_digest)\n                ELSE (\n                    SELECT revision.content::jsonb #> ''{spec,capabilities}''';
BEGIN
    v_definition := pg_get_functiondef(v_signature);
    IF (length(v_definition)-length(replace(v_definition,v_before,'')))/length(v_before) <> 1 THEN
        RAISE EXCEPTION 'integration grant admission predecessor changed';
    END IF;
    EXECUTE replace(v_definition,v_before,v_after);
END $admission$;
-- +goose StatementEnd
RESET ROLE;
